// Complete React Component with Responsive Navbar
import { Link } from 'react-router-dom';
import React, { useState, useEffect } from 'react';
import './Aiiot.css';

const AIIOT_INDEX = () => {
  // ========== NAVBAR STATE MANAGEMENT ==========
  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);
  const [expandedMobileDropdown, setExpandedMobileDropdown] = useState(null);
  
  // ========== EXISTING STATE ==========
  const [currentImageIndex, setCurrentImageIndex] = useState(0);
  const [projectsDropdownOpen, setProjectsDropdownOpen] = useState(false);
  const [heroImages, setHeroImages] = useState([]);
  const [isLoading, setIsLoading] = useState(true);
  const [resourcesDropdownOpen, setResourcesDropdownOpen] = useState(false);
  const [brochures, setBrochures] = useState([]);
  const [brochuresLoading, setBrochuresLoading] = useState(false);
  const [selectedCategory, setSelectedCategory] = useState(null);
  const [categories, setCategories] = useState([]);

  // Map project titles to IDs
  const projectIdMap = {
    'Intelligent Sensor Module': 'intelligent-sensor',
    'Smart Water Level Monitoring': 'water-level',
    'Digital Water Distribution': 'digital-water',
    'Startup & Skill Development': 'startup-skill',
    'Explainable AI Software': 'xai-software'
  };

  // ========== NAVBAR HANDLERS ==========

  // Toggle mobile menu
  const toggleMobileMenu = () => {
    setIsMobileMenuOpen(!isMobileMenuOpen);
  };

  // Toggle mobile dropdown
  const toggleMobileDropdown = (dropdownName) => {
    setExpandedMobileDropdown(expandedMobileDropdown === dropdownName ? null : dropdownName);
  };

  // Close mobile menu
  const closeMobileMenu = () => {
    setIsMobileMenuOpen(false);
    setExpandedMobileDropdown(null);
  };

  // Handle outside click
  useEffect(() => {
    const handleClickOutside = (event) => {
      const navElement = document.querySelector('nav');
      const hamburger = document.querySelector('.hamburger');
      
      if (navElement && !navElement.contains(event.target) && !hamburger?.contains(event.target)) {
        closeMobileMenu();
      }
    };

    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  // Handle window resize
  useEffect(() => {
    const handleResize = () => {
      if (window.innerWidth > 768) {
        closeMobileMenu();
      }
    };

    window.addEventListener('resize', handleResize);
    return () => window.removeEventListener('resize', handleResize);
  }, []);

  // ========== EXISTING FUNCTIONS ==========

  useEffect(() => {
    const fetchBrochures = async () => {
      setBrochuresLoading(true);
      try {
        const response = await fetch('http://127.0.0.1:8000/api/brochures/');
        if (!response.ok) throw new Error('Failed to fetch brochures');
        
        const data = await response.json();
        const brochureArray = data.results || data;
        
        if (brochureArray && brochureArray.length > 0) {
          const formattedBrochures = brochureArray.map(brochure => {
            const fileUrl = brochure.file;
            const finalUrl = fileUrl.startsWith('http') 
              ? fileUrl 
              : `http://127.0.0.1:8000${fileUrl}`;

            return {
              title: brochure.title,
              description: brochure.description,
              icon: brochure.icon || '📄',
              url: finalUrl,
              type: "PDF",
              category: brochure.category,
              id: brochure.id
            };
          });
          
          const uniqueCategories = [...new Set(formattedBrochures.map(b => b.category))];
          
          setBrochures(formattedBrochures);
          setCategories(uniqueCategories);
          setSelectedCategory(null);
        }
      } catch (error) {
        console.error('Error fetching brochures:', error);
      } finally {
        setBrochuresLoading(false);
      }
    };

    fetchBrochures();
  }, []);

  const filteredBrochures = selectedCategory 
    ? brochures.filter(b => b.category === selectedCategory)
    : brochures;

  useEffect(() => {
    if (window.feather) {
      window.feather.replace();
    }

    const scrollElements = document.querySelectorAll(".reveal-on-scroll");

    const elementInView = (el, dividend = 1) => {
      const elementTop = el.getBoundingClientRect().top;
      return elementTop <= (window.innerHeight || document.documentElement.clientHeight) / dividend;
    };

    const displayScrollElement = (element) => element.classList.add("is-visible");

    const handleScrollAnimation = () => {
      scrollElements.forEach((el) => {
        if (elementInView(el, 1.25)) displayScrollElement(el);
      });
    };

    handleScrollAnimation();
    window.addEventListener("scroll", handleScrollAnimation);
    setupCarousel();

    return () => {
      window.removeEventListener("scroll", handleScrollAnimation);
    };
  }, []);

  const setupCarousel = () => {
    const localImages = [
      '/carousel-images/aiiot1.jpg',
      '/carousel-images/aiiot2.jpeg',
      '/carousel-images/aiiot3.jpg',
      '/carousel-images/aiiot4.jpg',
    ];

    setHeroImages(localImages);
    setIsLoading(false);
  };

  useEffect(() => {
    if (heroImages.length === 0) return;

    const interval = setInterval(() => {
      setCurrentImageIndex((prevIndex) => (prevIndex + 1) % heroImages.length);
    }, 4000);

    return () => clearInterval(interval);
  }, [heroImages]);

  const handleIndicatorClick = (index) => {
    setCurrentImageIndex(index);
  };

  // ========== DATA ==========

  const teamMembers = [
    {
      name: "Dr. Ajay Kumar",
      role: "Principal Investigator",
      description: "Dr. Ajay Kumar is an Associate Professor at ASIET with a PhD in Electronics and Communication Engineering. His research interests include IoT and Wireless Sensor Networks.",
      image: "/faculties/ajay.jpeg"
    },
    {
      name: "Mr. Albins Paul",
      role: "Co-Investigator",
      description: "Assistant Professor at ASIET's ECE Department, specializing in Microwave & Television Engineering.",
      image: "/faculties/albins.jpg"
    },
    {
      name: "Prof. P.V. Rajaraman",
      role: "Co-Investigator",
      description: "Assistant Professor, CTO, and Head of the AI Department at ASIET. He specializes in NLP and XAI, has multiple publications, and is currently pursuing his Ph.D.",
      image: "/faculties/rajaraman.jpg"
    },
    {
      name: "Mr. Abhijith Pm",
      role: "Project Associate",
      description: "",
      image: "/faculties/abhijith.jpeg"
    },
    {
      name: "Mrs. Hasna Hameed",
      role: "Project Associate",
      description: "",
      image: "/faculties/hasna2.jpg"
    },
    {
      name: "Ms. Arathy Surendran",
      role: "Project Associate",
      description: "",
      image: "/faculties/arathy.jpg"
    },
    {
      name: "Mr. Bhagyaraj J",
      role: "Project Assistant",
      description: "",
      image: "/faculties/bhagyaraj.jpeg"
    },
    {
      name: "Mr. Amaljith N Raj",
      role: "Project Assistant",
      description: "",
      image: "/faculties/amaljith.jpg"
    },
    {
      name: "Mrs. Jibina EA",
      role: "Project Assistant",
      description: "",
      image: "/faculties/jibinaea.jpeg"
    }
  ];

  const projects = [
    {
      title: "Intelligent Sensor Module",
      description: "An advanced sensor module designed to collect real-time data from IoT devices. Features multi-sensor integration, low power consumption, and cloud connectivity for smart monitoring systems.",
      image: "/projects/sensor.jpg"
    },
    {
      title: "Smart Water Level Monitoring",
      description: "Real-time water level monitoring system for reservoirs and tanks. Uses ultrasonic sensors and IoT connectivity to provide instant alerts and historical data tracking.",
      image: "/projects/water.jpg"
    },
    {
      title: "Digital Water Distribution",
      description: "Smart water distribution network with automated control systems. Monitors flow rates, detects leaks, and optimizes water delivery using AI algorithms.",
      image: "/projects/distribution.jpg"
    },
    {
      title: "Startup & Skill Development",
      description: "Comprehensive program for developing startup ecosystems and technical skills. Includes mentoring, resources, and incubation support for tech entrepreneurs.",
      image: "/projects/startup.jpg"
    },
    {
      title: "Explainable AI Software",
      description: "Software solutions that make AI models interpretable and transparent. Provides visualizations and explanations for model decisions in business applications.",
      image: "/projects/xai.jpg"
    }
  ];

  // ========== RENDER ==========

  return (
    <div className="aiiot-page-container">
      {/* ========== RESPONSIVE NAVBAR ========== */}
      <nav>
        <div className="navbar-container">
          <Link to="/" className="navbar-logo" onClick={closeMobileMenu}>
            🤖 AI-IoT Lab
          </Link>

          {/* Desktop Navigation Menu */}
          <ul className={`nav-menu ${isMobileMenuOpen ? 'active' : ''}`}>
            <li className="nav-item">
              <a href="#about" className="nav-link" onClick={closeMobileMenu}>
                About
              </a>
            </li>

            <li className="nav-item">
              <a href="#team" className="nav-link" onClick={closeMobileMenu}>
                Team
              </a>
            </li>

            {/* Projects Dropdown */}
            <li className="nav-item dropdown" 
                className={expandedMobileDropdown === 'projects' ? 'nav-item dropdown active' : 'nav-item dropdown'}>
              <button
                className="nav-link dropdown-toggle"
                onClick={() => {
                  if (window.innerWidth <= 768) {
                    toggleMobileDropdown('projects');
                  } else {
                    setProjectsDropdownOpen(!projectsDropdownOpen);
                  }
                }}
              >
                Projects
              </button>
              <ul className="dropdown-menu">
                {projects.map((project, idx) => (
                  <li key={idx}>
                    <Link
                      to={`/project/${projectIdMap[project.title] || 'unknown'}`}
                      className="dropdown-item"
                      onClick={closeMobileMenu}
                    >
                      {project.title}
                    </Link>
                  </li>
                ))}
              </ul>
            </li>

            {/* Resources Dropdown */}
            <li className="nav-item dropdown"
                className={expandedMobileDropdown === 'resources' ? 'nav-item dropdown active' : 'nav-item dropdown'}>
              <button
                className="nav-link dropdown-toggle"
                onClick={() => {
                  if (window.innerWidth <= 768) {
                    toggleMobileDropdown('resources');
                  } else {
                    setResourcesDropdownOpen(!resourcesDropdownOpen);
                  }
                }}
              >
                Resources
              </button>
              <ul className="dropdown-menu">
                {categories.map((category, idx) => (
                  <li key={idx}>
                    <Link
                      to="#resources"
                      className="dropdown-item"
                      onClick={() => {
                        setSelectedCategory(category);
                        closeMobileMenu();
                      }}
                    >
                      {category}
                    </Link>
                  </li>
                ))}
              </ul>
            </li>

            <li className="nav-item">
              <a href="#contact" className="nav-link" onClick={closeMobileMenu}>
                Contact
              </a>
            </li>

            <li className="nav-item">
              <a href="mailto:contact@aiiot.edu" className="nav-cta" onClick={closeMobileMenu}>
                Get in Touch
              </a>
            </li>
          </ul>

          {/* Hamburger Menu */}
          <button
            className={`hamburger ${isMobileMenuOpen ? 'active' : ''}`}
            onClick={toggleMobileMenu}
            aria-label="Toggle menu"
            aria-expanded={isMobileMenuOpen}
          >
            <span></span>
            <span></span>
            <span></span>
          </button>
        </div>
      </nav>

      <main>
        {/* Hero Section */}
        <section id="hero" className="reveal-on-scroll" style={{ padding: '3rem 1rem', textAlign: 'center' }}>
          <div style={{ maxWidth: '900px', margin: '0 auto' }}>
            <h1 className="gradient-text" style={{ marginBottom: '1rem' }}>
              AI-IoT Innovations Lab
            </h1>
            <p style={{ fontSize: '1.125rem', marginBottom: '2rem', color: '#475569' }}>
              Pioneering the future of Artificial Intelligence and Internet of Things
            </p>
            {!isLoading && heroImages.length > 0 && (
              <div style={{ position: 'relative', borderRadius: '1rem', overflow: 'hidden', boxShadow: '0 20px 50px rgba(0,0,0,0.2)' }}>
                <img
                  src={heroImages[currentImageIndex]}
                  alt="AI-IoT Lab"
                  style={{ width: '100%', height: 'auto', maxHeight: '400px', objectFit: 'cover', display: 'block' }}
                  onError={(e) => {
                    e.target.style.display = 'none';
                    e.target.parentElement.style.background = '#eff6ff';
                    e.target.parentElement.style.minHeight = '300px';
                  }}
                />
                <div style={{ display: 'flex', justifyContent: 'center', gap: '0.5rem', marginTop: '1rem', flexWrap: 'wrap' }}>
                  {heroImages.map((_, index) => (
                    <button
                      key={index}
                      onClick={() => handleIndicatorClick(index)}
                      style={{
                        width: '12px',
                        height: '12px',
                        borderRadius: '50%',
                        background: currentImageIndex === index ? '#3b82f6' : '#cbd5e1',
                        border: 'none',
                        cursor: 'pointer',
                        transition: 'all 0.3s ease'
                      }}
                      aria-label={`Go to slide ${index + 1}`}
                    />
                  ))}
                </div>
              </div>
            )}
          </div>
        </section>

        {/* About Section */}
        <section id="about" className="reveal-on-scroll" style={{ padding: '4rem 1rem' }}>
          <div style={{ maxWidth: '1200px', margin: '0 auto' }}>
            <h2 style={{ fontSize: '2.25rem', fontWeight: 700, textAlign: 'center', marginBottom: '2rem', color: '#1e293b' }}>
              About Our Lab
            </h2>
            <p style={{ fontSize: '1rem', color: '#475569', lineHeight: 1.8, marginBottom: '1.5rem', textAlign: 'center', maxWidth: '800px', margin: '0 auto' }}>
              The AI-IoT Innovations Lab is dedicated to advancing the integration of Artificial Intelligence and Internet of Things technologies. Our mission is to develop cutting-edge solutions that address real-world challenges and drive digital transformation.
            </p>
          </div>
        </section>

        {/* Team Section */}
        <section id="team" className="reveal-on-scroll" style={{ padding: '4rem 1rem' }}>
          <div style={{ maxWidth: '1200px', margin: '0 auto' }}>
            <h2 style={{ fontSize: '2.25rem', fontWeight: 700, textAlign: 'center', marginBottom: '3rem', color: '#1e293b' }}>
              Meet Our Team
            </h2>
            <div style={{
              display: 'grid',
              gridTemplateColumns: 'repeat(auto-fit, minmax(250px, 1fr))',
              gap: '2rem'
            }}>
              {teamMembers.map((member, index) => (
                <div
                  key={index}
                  className="reveal-on-scroll"
                  style={{
                    background: 'white',
                    borderRadius: '1rem',
                    overflow: 'hidden',
                    boxShadow: '0 4px 20px rgba(0, 0, 0, 0.08)',
                    transition: 'all 0.3s ease',
                    textAlign: 'center',
                    padding: '1.5rem'
                  }}
                  onMouseEnter={(e) => {
                    e.currentTarget.style.transform = 'translateY(-5px)';
                    e.currentTarget.style.boxShadow = '0 12px 40px rgba(0, 0, 0, 0.15)';
                  }}
                  onMouseLeave={(e) => {
                    e.currentTarget.style.transform = 'translateY(0)';
                    e.currentTarget.style.boxShadow = '0 4px 20px rgba(0, 0, 0, 0.08)';
                  }}
                >
                  <img
                    src={member.image}
                    alt={member.name}
                    style={{
                      width: '100%',
                      height: '200px',
                      objectFit: 'cover',
                      borderRadius: '0.75rem',
                      marginBottom: '1rem'
                    }}
                    onError={(e) => {
                      e.target.style.background = '#eff6ff';
                    }}
                  />
                  <h4 style={{ fontSize: '1.125rem', fontWeight: 700, color: '#1e293b', marginBottom: '0.5rem' }}>
                    {member.name}
                  </h4>
                  <p style={{ fontSize: '0.875rem', color: '#3b82f6', fontWeight: 600, marginBottom: '0.75rem' }}>
                    {member.role}
                  </p>
                  <p style={{ fontSize: '0.875rem', color: '#475569', lineHeight: 1.6 }}>
                    {member.description}
                  </p>
                </div>
              ))}
            </div>
          </div>
        </section>

        {/* Resources Section */}
        <section id="resources" className="reveal-on-scroll" style={{ padding: '4rem 1rem' }}>
          <div style={{ maxWidth: '1200px', margin: '0 auto' }}>
            <h2 style={{ fontSize: '2.25rem', fontWeight: 700, textAlign: 'center', marginBottom: '2rem', color: '#1e293b' }}>
              Resources & Brochures
            </h2>
            
            {!brochuresLoading && categories.length > 0 && (
              <div style={{ display: 'flex', gap: '0.75rem', justifyContent: 'center', marginBottom: '2rem', flexWrap: 'wrap' }}>
                <button
                  onClick={() => setSelectedCategory(null)}
                  style={{
                    padding: '0.5rem 1rem',
                    background: !selectedCategory ? '#3b82f6' : '#e2e8f0',
                    color: !selectedCategory ? 'white' : '#1f2937',
                    border: 'none',
                    borderRadius: '0.5rem',
                    cursor: 'pointer',
                    fontWeight: 600,
                    transition: 'all 0.3s ease'
                  }}
                >
                  All
                </button>
                {categories.map((category, idx) => (
                  <button
                    key={idx}
                    onClick={() => setSelectedCategory(category)}
                    style={{
                      padding: '0.5rem 1rem',
                      background: selectedCategory === category ? '#3b82f6' : '#e2e8f0',
                      color: selectedCategory === category ? 'white' : '#1f2937',
                      border: 'none',
                      borderRadius: '0.5rem',
                      cursor: 'pointer',
                      fontWeight: 600,
                      transition: 'all 0.3s ease'
                    }}
                  >
                    {category}
                  </button>
                ))}
              </div>
            )}

            <div style={{
              display: 'grid',
              gridTemplateColumns: 'repeat(auto-fit, minmax(280px, 1fr))',
              gap: '2rem'
            }}>
              {filteredBrochures.map((brochure, idx) => (
                <div
                  key={idx}
                  className="reveal-on-scroll"
                  style={{
                    background: 'white',
                    borderRadius: '1rem',
                    padding: '1.5rem',
                    boxShadow: '0 4px 20px rgba(0, 0, 0, 0.08)',
                    transition: 'all 0.3s ease',
                    display: 'flex',
                    flexDirection: 'column'
                  }}
                >
                  <div style={{ fontSize: '2rem', marginBottom: '1rem' }}>
                    {brochure.icon}
                  </div>
                  <h4 style={{ fontSize: '1.125rem', fontWeight: 700, color: '#1e293b', marginBottom: '0.5rem' }}>
                    {brochure.title}
                  </h4>
                  <p style={{ fontSize: '0.875rem', color: '#475569', marginBottom: '1rem', flex: 1 }}>
                    {brochure.description}
                  </p>
                  <a
                    href={brochure.url}
                    target="_blank"
                    rel="noopener noreferrer"
                    style={{
                      display: 'inline-flex',
                      alignItems: 'center',
                      gap: '0.5rem',
                      padding: '0.75rem 1.5rem',
                      background: '#3b82f6',
                      color: 'white',
                      fontWeight: 600,
                      borderRadius: '0.5rem',
                      textDecoration: 'none'
                    }}
                  >
                    Download {brochure.icon}
                  </a>
                </div>
              ))}
            </div>
          </div>
        </section>

        {/* Projects Section */}
        <section id="projects" className="reveal-on-scroll" style={{ padding: '4rem 1rem' }}>
          <div style={{ maxWidth: '1200px', margin: '0 auto' }}>
            <h2 style={{ fontSize: '2.25rem', fontWeight: 700, textAlign: 'center', marginBottom: '3rem', color: '#1e293b' }}>
              Our Projects
            </h2>

            <div style={{ display: 'flex', flexDirection: 'column', gap: '3rem' }}>
              {projects.map((project, index) => {
                const projectId = projectIdMap[project.title] || 'unknown';
                return (
                  <div 
                    key={index}
                    className="reveal-on-scroll"
                    style={{
                      display: 'flex',
                      alignItems: 'center',
                      gap: '2rem',
                      flexDirection: index % 2 === 0 ? 'row' : 'row-reverse',
                    }}
                  >
                    <div style={{ flex: '0 0 45%', minWidth: 0 }}>
                      <img 
                        src={project.image}
                        alt={project.title}
                        style={{
                          width: '100%',
                          height: '280px',
                          objectFit: 'cover',
                          borderRadius: '1rem',
                          boxShadow: '0 10px 30px rgba(0, 0, 0, 0.15)'
                        }}
                        onError={(e) => {
                          e.target.style.display = 'none';
                          e.target.parentElement.style.background = '#eff6ff';
                        }}
                      />
                    </div>

                    <div style={{ flex: '0 0 55%' }}>
                      <h3 style={{
                        fontSize: '1.875rem',
                        fontWeight: 700,
                        color: '#1e293b',
                        marginBottom: '1rem'
                      }}>
                        {project.title}
                      </h3>
                      <p style={{
                        fontSize: '1rem',
                        color: '#475569',
                        lineHeight: 1.8,
                        marginBottom: '1.5rem'
                      }}>
                        {project.description}
                      </p>
                      <Link 
                        to={`/project/${projectId}`}
                        onClick={() => window.scrollTo(0, 0)}
                        style={{
                          display: 'inline-flex',
                          alignItems: 'center',
                          gap: '0.5rem',
                          padding: '0.75rem 1.5rem',
                          background: '#3b82f6',
                          color: 'white',
                          fontSize: '0.875rem',
                          fontWeight: 600,
                          borderRadius: '0.5rem',
                          textDecoration: 'none'
                        }}
                      >
                        Learn More 
                        <span style={{ fontSize: '1.125rem' }}>→</span>
                      </Link>
                    </div>
                  </div>
                );
              })}
            </div>
          </div>
        </section>

        {/* Contact Section */}
        <section id="contact" className="reveal-on-scroll" style={{ padding: '5rem 1rem', background: '#f8fafc' }}>
          <div style={{ maxWidth: '48rem', margin: '0 auto', textAlign: 'center' }}>
            <h2 style={{ fontSize: '2.25rem', fontWeight: 700, color: '#1e293b', marginBottom: '1rem' }}>
              Let's Build the Future Together
            </h2>
            <p style={{ fontSize: '1.125rem', color: '#475569', marginBottom: '2rem' }}>
              Have a project in mind, a question, or want to collaborate? We'd love to hear from you.
            </p>
            <a href="mailto:contact@aiiot.edu" style={{
              display: 'inline-flex',
              alignItems: 'center',
              gap: '0.5rem',
              padding: '0.75rem 1.5rem',
              background: '#3b82f6',
              color: 'white',
              fontWeight: 500,
              borderRadius: '0.5rem'
            }}>
              <span>✉️</span>
              Contact Us
            </a>
          </div>
        </section>
      </main>

      {/* Footer */}
      <footer style={{ background: '#1e293b', color: '#cbd5e1', padding: '3rem 1rem', position: 'relative', zIndex: 10 }}>
        <div style={{ maxWidth: '1200px', margin: '0 auto' }}>
          <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(250px, 1fr))', gap: '2rem', marginBottom: '2rem' }}>
            <div>
              <h5 style={{ fontWeight: 700, color: 'white', marginBottom: '1rem' }}>AI-IoT Innovations</h5>
              <p style={{ fontSize: '0.875rem' }}>
                Advancing the integration of AI and IoT technologies for a smarter tomorrow.
              </p>
            </div>
            
            <div>
              <h5 style={{ fontWeight: 700, color: 'white', marginBottom: '1rem' }}>Quick Links</h5>
              <ul style={{ listStyle: 'none', padding: 0, margin: 0 }}>
                {['About', 'Team', 'Projects', 'Contact'].map((link, idx) => (
                  <li key={idx} style={{ marginBottom: '0.5rem' }}>
                    <a href={`#${link.toLowerCase()}`} style={{ color: 'white', textDecoration: 'none' }}>
                      {link}
                    </a>
                  </li>
                ))}
              </ul>
            </div>
            
            <div>
              <h3 style={{ color: 'white', fontWeight: 700, marginBottom: '1rem' }}>Contact Information</h3>
              <p style={{ fontSize: '0.875rem', color: '#cbd5e1' }}>
                Adi Shankara Institute of Engineering and Technology<br />
                Kalady 683574, Ernakulam<br />
                Kerala, India
              </p>
            </div>
          </div>
          
          <div style={{
            borderTop: '1px solid #334155',
            paddingTop: '2rem',
            textAlign: 'center',
            fontSize: '0.875rem'
          }}>
            <p>&copy; 2025 Center for AI-IoT Innovations. All rights reserved.</p>
          </div>
        </div>
      </footer>
    </div>
  );
};

export default AIIOT_INDEX;
